const sid = 'demo-' + Date.now() + '-' + Math.floor(Math.random()*100000);
const action = '/webhook/favfare-demo/patient-action-v3';
const h = (n,v) => `<input type="hidden" name="${n}" value="${v}">`;
const quick = (label,msg) => `<form method="post" action="${action}">${h('action','chat')}${h('session_id',sid)}${h('message',msg)}<button>${label}</button></form>`;
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Favfare Patient Assistant</title>
<style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#e7eee9;color:#17241e;min-height:100vh;display:grid;place-items:center;padding:22px}
.wrap{width:min(1050px,100%);display:grid;grid-template-columns:1fr 400px;gap:38px;align-items:center}.intro small{font-weight:850;letter-spacing:.14em;color:#426454}.intro h1{font-size:44px;letter-spacing:-.04em;margin:10px 0}.intro p{color:#65716b;line-height:1.7;max-width:560px}
.note{background:white;padding:18px;border-radius:18px;margin-top:24px;border:1px solid #d9e3dc}.note span{font-size:12px;color:#6a756f}.crm{display:inline-block;margin-top:16px;color:#2e5b49;font-weight:750;text-decoration:none}
.phone{height:760px;max-height:90vh;background:#efeae2;border-radius:26px;overflow:hidden;box-shadow:0 24px 70px rgba(16,50,36,.22);display:flex;flex-direction:column}.top{background:#075e54;color:white;padding:14px 16px;display:flex;gap:12px;align-items:center}.avatar{width:42px;height:42px;border-radius:50%;background:white;color:#075e54;display:grid;place-items:center;font-weight:900}.top strong{display:block}.top span{font-size:12px;opacity:.82}.status{font-size:11px;padding:7px 12px;background:#fff7cf;text-align:center;color:#715800}
.chat{flex:1;overflow:auto;padding:18px 14px;background-image:radial-gradient(rgba(0,0,0,.025) 1px,transparent 1px);background-size:18px 18px}.msg{display:flex;margin:9px 0}.bubble{max-width:84%;padding:10px 12px;border-radius:9px;line-height:1.45;font-size:14px;box-shadow:0 1px 1px rgba(0,0,0,.08);background:white;border-top-left-radius:2px}
.controls{padding:10px;background:#f0f2f5}.quick{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:8px}.quick form{margin:0}.quick button{width:100%;min-height:40px;border:1px solid #a9c7b8;background:white;color:#12624c;padding:8px;border-radius:12px;font-weight:750;cursor:pointer}.composer{display:flex;gap:8px}.composer input{flex:1;border:0;border-radius:22px;padding:12px 15px;font-size:14px;outline:none}.composer button{width:44px;height:44px;border:0;border-radius:50%;background:#00a884;color:white;font-size:18px;cursor:pointer}.detected{font-size:10px;color:#6f7c76;margin:5px 4px 0}
@media(max-width:850px){.wrap{grid-template-columns:1fr}.intro h1{font-size:34px}.phone{height:78vh}}
</style></head><body><div class="wrap"><section class="intro"><small>BIZI SYSTEMS · LIVE SALES DEMO</small><h1>Favfare Patient Assistant</h1><p>A WhatsApp-style sales assistant that asks useful questions, recommends relevant services, checks live appointment availability, sends qualified requests to the clinic team, and reflects staff booking decisions back into the patient conversation.</p><div class="note"><strong>Natural conversation first</strong><br><span>Structured service and time choices appear only when they make the decision easier.</span></div><a class="crm" href="/webhook/favfare-demo/crm-ui" target="_blank">Open staff CRM ↗</a></section><section class="phone"><div class="top"><div class="avatar">F</div><div><strong>Favfare The Clinic</strong><span>Patient Assistant · online</span></div></div><div class="status">Demo · appointment requests require staff confirmation</div><div class="chat"><div class="msg"><div class="bubble">Hi 👋 Welcome to Favfare. What would you like help with today?</div></div></div><div class="controls"><div class="quick">${quick('Teeth cleaning','I want to clean my teeth')}${quick('Whiter teeth','I want whiter teeth')}${quick('View services','Show me your services')}${quick('Book appointment','I want to book an appointment')}</div><form class="composer" method="post" action="${action}">${h('action','chat')}${h('session_id',sid)}<input name="message" placeholder="Type a message" autocomplete="off" required><button>➤</button></form><div class="detected">In production WhatsApp, the sender number is captured automatically.</div></div></section></div></body></html>`;
return [{json:{html}}];
